using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using PersonalFinance.Api.Domain;
namespace PersonalFinance.Api.Application;
public sealed record ConcertPlanBudget(string Name,int Year,string Currency,string Scope,string? ReferenceId,string Amount,string? GoalId,string? HoldId,string AssumedPerShow,string Note);
public sealed partial class FinanceService {
 public async Task<object> ConcertPlanningSources(string user,string? keyword) {
  await RequireConcerts(user);Require((keyword?.Length??0)<=100,"搜索文字过长");keyword??="";
  return new{goals=await db.Set<SavingsGoal>().AsNoTracking().Where(g=>g.UserId==user && g.Name.Contains(keyword)).OrderByDescending(g=>g.CreatedAt).Take(100).Select(g=>new{g.Id,g.Name,g.Currency}).ToArrayAsync(),holds=await db.Set<AccountFundHold>().AsNoTracking().Where(h=>h.UserId==user && (h.Note.Contains(keyword)||h.Type.Contains(keyword))).OrderByDescending(h=>h.CreatedAt).Take(100).Select(h=>new{h.Id,name=h.Type+" · "+h.Note,h.Currency}).ToArrayAsync(),prepayments=await db.Set<PrepaymentContract>().AsNoTracking().Where(p=>p.UserId==user && p.Name.Contains(keyword)).OrderByDescending(p=>p.CreatedAt).Take(100).Select(p=>new{p.Id,p.Name,p.Currency}).ToArrayAsync()};
 }
 public async Task<object> SaveConcertPlanBudget(string user,string? id,ConcertPlanBudget input,string? version) {
  await RequireConcerts(user);ConcertText(input.Name,200,true);ConcertText(input.Note,2000);Require(input.Year is >=1900 and <=9900 && CurrencyDefinitions.Supports(input.Currency) && Money(input.Amount)>=0 && Money(input.AssumedPerShow)>=0 && input.Scope is "Annual" or "Scene" or "Tour" or "Trip" or "Ticket" or "Daily" or "Brand","预算范围、年度或金额无效");
  if(input.Scope is "Scene" or "Tour" or "Trip" or "Brand"){Require(input.ReferenceId!=null,"请选择预算对象");await Document(user,input.ReferenceId!,input.Scope switch{"Scene"=>"ConcertScene","Tour"=>ConcertTourKind,"Trip"=>ConcertTripKind,_=>"MusicTopic"});if(input.Scope=="Brand")await RequireInterestTopic(user,input.ReferenceId,"Brand");}
  if(input.GoalId!=null)Require(await db.Set<SavingsGoal>().AnyAsync(g=>g.UserId==user && g.Id==input.GoalId && g.Currency==input.Currency),"储蓄目标不属于本人同币种");if(input.HoldId!=null)Require(await db.Set<AccountFundHold>().AnyAsync(h=>h.UserId==user && h.Id==input.HoldId && h.Currency==input.Currency),"资金预留不属于本人同币种");return await SaveInterestDocument(user,"ConcertPlanBudget",id,input,version);
 }
 public async Task<object> ConcertPlanBudgets(string user) {
  await RequireConcerts(user);var result=new List<object>();var scenes=await ConcertDocs(user);
  foreach(var d in await InterestDocs(user,"ConcertPlanBudget")){var b=InterestRead<ConcertPlanBudget>(d);decimal actual=0;
   if(b.Scope is "Annual" or "Scene" or "Ticket" or "Tour"){foreach(var scene in scenes){var c=ConcertRead(scene);if(c.Currency!=b.Currency || ConcertRules.LocalStart(c).Year!=b.Year || b.Scope=="Tour" && c.TourId!=b.ReferenceId || b.Scope=="Scene" && scene.Id!=b.ReferenceId)continue;var report=JsonSerializer.SerializeToElement(await ConcertReport(user,scene),Json);actual+=b.Scope=="Ticket"?report.GetProperty("categories").EnumerateArray().Where(x=>x.GetProperty("category").GetString()=="Ticket").Sum(x=>Money(x.GetProperty("actual").GetString())):Money(report.GetProperty("personalNetCost").GetString());}}
   else if(b.Scope=="Trip"){var trips=JsonSerializer.SerializeToElement(await ConcertTrips(user),Json);var row=trips.EnumerateArray().FirstOrDefault(t=>t.GetProperty("id").GetString()==b.ReferenceId);if(row.ValueKind!=JsonValueKind.Undefined  )actual=row.GetProperty("report").GetProperty("currencyTotals").EnumerateArray().Where(t=>t.GetProperty("currency").GetString()==b.Currency).Sum(t=>Money(t.GetProperty("occurred").GetString()));}
   else{var report=JsonSerializer.SerializeToElement(await InterestReport(user,b.Currency,b.Year,null,b.Scope=="Brand"?b.ReferenceId:null,null,null),Json);actual=Money(report.GetProperty(b.Scope=="Daily"?"daily":"totals").GetProperty("net").GetString());}
   var remaining=Money(b.Amount)-actual;decimal goalAllocated=0,held=0;if(b.GoalId!=null)goalAllocated=await db.Set<GoalAllocation>().Where(g=>g.UserId==user && g.GoalId==b.GoalId).SumAsync(g=>(decimal?)g.Amount)??0;if(b.HoldId!=null){var hold=await db.Set<AccountFundHold>().AsNoTracking().SingleOrDefaultAsync(h=>h.UserId==user && h.Id==b.HoldId && h.Currency==b.Currency);if(hold!=null && hold.State=="Active")held=Math.Max(0,hold.Amount-hold.ReleasedAmount-hold.SettledAmount);}
   result.Add(new{d.Id,version=d.Version.ToString(),input=b,report=new{actual=M(actual),remaining=M(remaining),overspent=M(Math.Max(0,-remaining)),warning=actual>Money(b.Amount),goalAllocated=M(goalAllocated),held=M(held),affordableAdditionalShows=Money(b.AssumedPerShow)>0?(decimal?)decimal.Floor(Math.Max(0,remaining)/Money(b.AssumedPerShow)):null,rule="预算是独立分析上限，不再次占用全局预算或资金。各范围不可相加；年度/单场/巡演用个人费用，票务用全场门票净费用，旅行用所选行程全周期原币费用。资金预留与储蓄归属只读取原服务，不互相加作可用现金；可承受场次仅按用户假设单价估算。"}});
  }return result;
 }
 public async Task<object> ConcertOverview(string user,string currency,int year) {
  await RequireConcerts(user);Require(CurrencyDefinitions.Supports(currency) && year is >=1900 and <=9900,"参数无效");var docs=await ConcertDocs(user);var scenes=docs.Select(d=>(d.Id,Input:ConcertRead(d))).ToArray();var annual=await ConcertAnnualReport(user,year,currency);var interest=await InterestReport(user,currency,year,null,null,null,null);var now=DateTimeOffset.UtcNow;var upcoming=scenes.Where(s=>s.Input.StartsAt>now && s.Input.State is not ("Cancelled" or "Attended")).OrderBy(s=>s.Input.StartsAt).Take(5).Select(s=>new{s.Id,s.Input.Title,s.Input.StartsAt,s.Input.TimeZone,daysUntil=(int)Math.Ceiling((s.Input.StartsAt-now).TotalDays)}).ToArray();
  var memories=(await InterestDocs(user,"ConcertMemory")).Select(d=>new{d.Id,input=InterestRead<ConcertMemory>(d)}).ToArray();var trips=(await InterestDocs(user,ConcertTripKind)).Select(d=>new{d.Id,input=InterestRead<ConcertTrip>(d)}).Where(t=>t.input.State is "Planning" or "Booked").ToArray();
  return new{currency,year,annual,interest,upcoming,unusedTickets=scenes.Where(s=>s.Input.State!="Cancelled" && s.Input.StartsAt>=now).Sum(s=>s.Input.Orders.SelectMany(o=>o.Tickets??[]).Count(t=>t.State=="Received")),pendingRefunds=scenes.Sum(s=>s.Input.Refunds.Count(r=>r.State is "Requested" or "Approved" || r.State=="Partial" && Money(r.ReceivedAmount)<Money(r.RequestedAmount))),memories,trips,recent=scenes.Where(s=>s.Input.StartsAt<=now).OrderByDescending(s=>s.Input.StartsAt).Take(5).Select(s=>new{s.Id,s.Input.Title,s.Input.StartsAt}),rule="指标来自原场次、日常消费及行程/回忆档案；原币分别统计。待收、待退、计划和收藏估值不计作现金或新增资产。"};
 }
}
